import{_ as n,a0 as u,w as r,s as l,ao as o,I as a,x as p,a1 as d,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"apt 的 update 和 upgrade 命令的区别是什么？ | LCTT x X-CMD","titleTemplate":false,"description":"apt 的 update 和 upgrade 命令的区别是什么？ | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"apt 的 update 和 upgrade 命令的区别是什么？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"apt 的 update 和 upgrade 命令的区别是什么？ | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220824 sudo apt update vs upgrade- What-s the Difference-","title":"apt 的 update 和 upgrade 命令的区别是什么？","tag":"202209","desc":""},"relativePath":"202209/20220824 sudo apt update vs upgrade- What-s the Difference-.md","filePath":"[post].md"}'),g={name:"202209/20220824 sudo apt update vs upgrade- What-s the Difference-.md"};function i(m,t,f,c,b,T){const e=u("Link");return r(),l("div",null,[t[40]||(t[40]=o('<h1 id="apt-的-update-和-upgrade-命令的区别是什么" tabindex="-1">apt 的 update 和 upgrade 命令的区别是什么？ <a class="header-anchor" href="#apt-的-update-和-upgrade-命令的区别是什么" aria-label="Permalink to “apt 的 update 和 upgrade 命令的区别是什么？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/02/224416uecz5x75yalc0axc.jpg" alt=""></p><p>如果想让你的 Ubuntu 或者 Debian 系统保持更新，要用 <code>sudo apt update</code> 和 <code>sudo apt upgrade</code> 命令组合。</p><p>一些以前的教程也会提到 <code>sudo apt-get update</code> 和 <code>sudo apt-get upgrade</code>。</p><p><code>apt</code> 和 <code>apt-get</code> 命令运行起来几乎一样，除了一些细微的差别，后面我会讨论。</p><p>我们首先讨论一下 <code>update</code> 和 <code>upgrade</code> 的区别。这两个难道不是一样的吗？</p><h3 id="apt-的-update-和-upgrade-的区别" tabindex="-1">apt 的 update 和 upgrade 的区别 <a class="header-anchor" href="#apt-的-update-和-upgrade-的区别" aria-label="Permalink to “apt 的 update 和 upgrade 的区别”">​</a></h3><p>尽管听上去运行 <code>apt update</code> 可以给你一个包的最新版本，然而这并不正确。<code>update</code> 命令只会获得系统上所有包的最新信息，并不会下载或者安装任何一个包。而是 <code>apt upgrade</code> 命令来把这些包下载和升级到最新版本。</p>',8)),a("p",null,[t[1]||(t[1]=p("还是有点困惑？让我来接着解释。我建议阅读 ",-1)),d(e,{href:"https://itsfoss.com/package-manager/"},{default:s(()=>[...t[0]||(t[0]=[p("包管理器的概念",-1)])]),_:1}),t[2]||(t[2]=p("。这个会帮你更好的理解这些东西。",-1))]),t[41]||(t[41]=o('<p><img src="https://itsfoss.com/wp-content/uploads/2020/10/linux-package-manager-explanation.png" alt="Linux Package Manager Explanation"></p><p>基本上，你的系统围绕着一个所有可用包的数据库（缓存）工作。注意，这个缓存（或者数据库）并不包含这些包本身，仅仅是关于包的元数据（版本、仓库、依赖等）。</p><p>如果你不更新这个数据库，系统就不会知道是否有更新的版本。</p><p>当你运行 <code>apt update</code> 或者 <code>apt-get update</code> 命令，它会获取这些包的最新元数据（包的版本等）。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-update.png" alt="apt update"></p><p>这时候本地缓存就被更新了，有一些包可以升级。用 <code>sudo apt upgrade</code> 可以升级所有（可升级的）包。</p><p>它会显示要升级的包，并且通过回车（默认选择是 <code>Y</code>）或者按下 <code>Y</code> 键进行确认。要在这个阶段取消升级，可以按下 <code>N</code>。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-upgrade.png" alt="apt upgrade"></p><p>下面这些可能会帮助你记忆：</p><ul><li><code>apt update</code>：更新包缓存（可以知道包的哪些版本可以被安装或升级）</li><li><code>apt upgrade</code>：升级包到最新版本</li></ul><p>因为有一些管理员命令，需要作为 root 运行。因此需要使用 <code>sudo</code> 配合其他命令。<code>sudo</code> 使你能够作为 root 在 Ubuntu 和 Debian 上运行命令。</p><p>既然理解了 <code>update</code> 和 <code>upgrade</code> 是如何一起运行的，我们接下来来讨论一下 <code>apt</code> 和 <code>apt-get</code> 的用法。</p><h3 id="apt-还是-apt-get-应该用哪个" tabindex="-1">apt 还是 apt-get？应该用哪个？ <a class="header-anchor" href="#apt-还是-apt-get-应该用哪个" aria-label="Permalink to “apt 还是 apt-get？应该用哪个？”">​</a></h3><p>Debian 和 Ubuntu 使用的是 APT 包管理系统。不要和 <code>apt</code> 命令弄混了。</p><p>有许多和 APT 包管理交互的命令；<code>apt-get</code>、<code>apt</code>、<code>dpkg</code>、<code>aptitude</code> 等。</p><p>这里面最受欢迎的就是 <code>apt-get</code> 命令。它是一个<ruby>低层级<rt>low-level</rt></ruby>且功能丰富的命令。<code>apt</code> 是 <code>apt-get</code> 命令的一个更新而更简单的版本。</p>',16)),a("p",null,[t[4]||(t[4]=p("可以读一下这篇文章来 ",-1)),d(e,{href:"https://itsfoss.com/apt-get-upgrade-vs-dist-upgrade/"},{default:s(()=>[...t[3]||(t[3]=[p("了解 atp 和 apt-get 命令的不同",-1)])]),_:1}),t[5]||(t[5]=p("。下面重点讨论这些命令中 ",-1)),t[6]||(t[6]=a("code",null,"update",-1)),t[7]||(t[7]=p(" 和 ",-1)),t[8]||(t[8]=a("code",null,"upgrade",-1)),t[9]||(t[9]=p(" 选项的区别。",-1))]),t[42]||(t[42]=o(`<h4 id="apt-update-vs-apt-get-update" tabindex="-1">apt update vs apt-get update <a class="header-anchor" href="#apt-update-vs-apt-get-update" aria-label="Permalink to “apt update vs apt-get update”">​</a></h4><p><code>apt-get update</code> 和 <code>apt update</code> 做的是同样的事，都是更新本地包缓存，这样的话你的系统就知道有哪些包的版本是可用的。</p><p>从技术上讲，其实并没有区别。然而，<code>apt update</code> 在一个方面比 <code>apt-get update</code> 做的好，<strong>它会告诉你可升级的包的数量</strong>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hit:15 https://ppa.launchpadcontent.net/slimbook/slimbook/ubuntu jammy InRelease</span></span>
<span class="line"><span>Fetched 213 kB in 4s (55.8 kB/s)</span></span>
<span class="line"><span>Reading package lists... Done</span></span>
<span class="line"><span>Building dependency tree... Done</span></span>
<span class="line"><span>Reading state information... Done</span></span>
<span class="line"><span>6 packages can be upgraded. Run &#39;apt list --upgradable&#39; to see them.</span></span></code></pre></div><p><code>apt-get update</code> 甚至不会告诉你包是否可以升级。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-get-update.png" alt="apt get update"></p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-update-output.png" alt="apt update output"></p>`,7)),a("p",null,[t[11]||(t[11]=p("从 ",-1)),t[12]||(t[12]=a("code",null,"apt",-1)),t[13]||(t[13]=p(" 中可以看到 ",-1)),d(e,{href:"https://itsfoss.com/apt-list-upgradable/"},{default:s(()=>[...t[10]||(t[10]=[p("列出可升级的包",-1)])]),_:1}),t[14]||(t[14]=p("，而 ",-1)),t[15]||(t[15]=a("code",null,"apt-get",-1)),t[16]||(t[16]=p(" 甚至没有这个选项。",-1))]),t[43]||(t[43]=o(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt list --upgradable</span></span>
<span class="line"><span>Listing... Done</span></span>
<span class="line"><span>fprintd/jammy-updates 1.94.2-1ubuntu0.22.04.1 amd64 [upgradable from: 1.94.2-1]</span></span>
<span class="line"><span>gnome-control-center-data/jammy-updates,jammy-updates 1:41.7-0ubuntu0.22.04.4 all [upgradable from: 1:41.7-0ubuntu0.22.04.1]</span></span>
<span class="line"><span>gnome-control-center-faces/jammy-updates,jammy-updates 1:41.7-0ubuntu0.22.04.4 all [upgradable from: 1:41.7-0ubuntu0.22.04.1]</span></span>
<span class="line"><span>gnome-control-center/jammy-updates 1:41.7-0ubuntu0.22.04.4 amd64 [upgradable from: 1:41.7-0ubuntu0.22.04.1]</span></span>
<span class="line"><span>libpam-fprintd/jammy-updates 1.94.2-1ubuntu0.22.04.1 amd64 [upgradable from: 1.94.2-1]</span></span>
<span class="line"><span>vivaldi-stable/stable 5.4.2753.40-1 amd64 [upgradable from: 5.4.2753.37-1]</span></span></code></pre></div><p>现在来比较一下两个命令中 <code>upgrade</code> 的选项。</p><h4 id="apt-upgrade-vs-apt-get-upgrade" tabindex="-1">apt upgrade vs apt-get upgrade <a class="header-anchor" href="#apt-upgrade-vs-apt-get-upgrade" aria-label="Permalink to “apt upgrade vs apt-get upgrade”">​</a></h4><p><code>apt-get upgrade</code> 和 <code>apt upgrade</code> 命令根据本地包缓存（通过 <code>update</code> 命令更新）的数据，安装可升级包的最新版本。</p><p>然而，<code>apt upgrade</code> 命令会做两件与 <code>apt-get upgrade</code> 不同的事情。</p>`,5)),a("p",null,[t[18]||(t[18]=a("code",null,"apt upgrade",-1)),t[19]||(t[19]=p(" 命令可以升级 Linux 内核版本，",-1)),t[20]||(t[20]=a("code",null,"apt-get upgrade",-1)),t[21]||(t[21]=p(" 不能。",-1)),t[22]||(t[22]=a("code",null,"apt-get",-1)),t[23]||(t[23]=p(" 命令需要使用 ",-1)),d(e,{href:"https://itsfoss.com/apt-get-upgrade-vs-dist-upgrade/"},{default:s(()=>[...t[17]||(t[17]=[p("apt-get dist-upgrade",-1)])]),_:1}),t[24]||(t[24]=p(" 来升级内核版本。",-1))]),t[44]||(t[44]=o('<p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-get-upgrade.png" alt="apt-get upgrade command cannot upgrade Linux kernel version"></p><p>这是因为升级内核版本意味着安装一个全新的包。<code>apt-get upgrade</code> 命令不能安装一个新的包。它只能升级现有的包。</p><p><code>apt upgrade</code> 比 <code>apt-get</code> 做的好的另一件小事是，它会在底部<strong>显示一个进度条</strong>。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-upgrade-progress-bar.png" alt="apt upgrade progress bar"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p><code>update</code> 和 <code>upgrade</code> 两个词很相似，这就是为什么很多新用户会感到困惑。有时候，我觉得 <code>apt update</code> 命令应该和 <code>apt upgrade</code> 命令合并。</p><p>我意思是 <code>upgrade</code>（所有已安装的包）和 <code>update</code>（本地包元数据缓存）一起完成工作。为什么要有两个分开的命令呢？把这两个领命合成一个 <code>upgrade</code> 命令吧。Fedora 就是这样对 DNF 命令进行了改进。不过这只是我的观点。</p><p>我希望这篇文章可以解释一些关于 <code>apt-get update</code>、<code>apt-get upgrade</code> 和 <code>apt update</code> 以及 <code>apt upgrade</code> 命令的问题。</p><p>如果有任何问题，请与我联系。</p><hr>',10)),a("p",null,[t[26]||(t[26]=p("via: ",-1)),d(e,{href:"https://itsfoss.com/apt-update-vs-upgrade/"},{default:s(()=>[...t[25]||(t[25]=[p("https://itsfoss.com/apt-update-vs-upgrade/",-1)])]),_:1})]),a("p",null,[t[31]||(t[31]=p("作者：",-1)),d(e,{href:"https://itsfoss.com/"},{default:s(()=>[...t[27]||(t[27]=[p("Abhishek Prakash",-1)])]),_:1}),t[32]||(t[32]=p(" 选题：",-1)),d(e,{href:"https://github.com/lkxed"},{default:s(()=>[...t[28]||(t[28]=[p("lkxed",-1)])]),_:1}),t[33]||(t[33]=p(" 译者：",-1)),d(e,{href:"https://github.com/Yufei-Yan"},{default:s(()=>[...t[29]||(t[29]=[p("Yufei-Yan",-1)])]),_:1}),t[34]||(t[34]=p(" 校对：",-1)),d(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[30]||(t[30]=[p("wxy",-1)])]),_:1})]),a("p",null,[t[37]||(t[37]=p("本文由 ",-1)),d(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[35]||(t[35]=[p("LCTT",-1)])]),_:1}),t[38]||(t[38]=p(" 原创编译，",-1)),d(e,{href:"https://linux.cn/"},{default:s(()=>[...t[36]||(t[36]=[p("Linux中国",-1)])]),_:1}),t[39]||(t[39]=p(" 荣誉推出",-1))])])}const C=n(g,[["render",i]]);export{v as __pageData,C as default};
